_DS_ID_RE = re.compile(r"^[a-f0-9]{1,64}$")


def safe_dataset_path(did):
    did = (did or "").strip()
    if not _DS_ID_RE.fullmatch(did):
        return None
    p = (DATA_DIR / (did + ".txt")).resolve()
    if p.parent != DATA_DIR.resolve():
        return None
    return p


def _trim_ram():
    import gc
    gc.collect()
    try:
        import ctypes
        ctypes.CDLL("libc.so.6").malloc_trim(0)
    except Exception:
        pass


def _is_private_webhook_target(url):
    try:
        from urllib.parse import urlsplit
        u = urlsplit(url)
        if u.scheme not in ("http", "https"):
            return True
        host = (u.hostname or "").strip().lower()
        if not host:
            return True
        if host in ("localhost", "ip6-localhost", "ip6-loopback") or \
                host.endswith(".localhost") or host.endswith(".internal"):
            return True
        import ipaddress
        try:
            ip = ipaddress.ip_address(host)
        except ValueError:
            return False
        return ip.is_private or ip.is_loopback or ip.is_link_local or \
            ip.is_reserved or ip.is_multicast or ip.is_unspecified
    except Exception:
        return True


def _clean_webhook_headers(headers):
    out = {}
    for k, v in (dict(headers or {})).items():
        k = re.sub(r"[\r\n\x00-\x1f\x7f]", "", str(k))[:64]
        v = re.sub(r"[\r\n\x00-\x1f\x7f]", "", str(v))[:512]
        if k and k.lower() not in ("content-length", "transfer-encoding",
                                   "content-type", "host"):
            out[k] = v
        if len(out) >= 10:
            break
    return out


def dbcon():
    con = sqlite3.connect(DB, timeout=30)
    con.row_factory = sqlite3.Row
    return con


def init_db():
    con = dbcon()
    with con:
        con.execute("""create table if not exists runs(
            id integer primary key autoincrement,
            ts text, model text, samples int, status text,
            loss real, dur real, out_dir text, cfg text)""")
        con.execute("create table if not exists settings(k text primary key, v text)")
        con.execute("""create table if not exists jobs(
            id integer primary key autoincrement,
            ts text, cfg text, status text, webhook text, headers text,
            run_id integer, result text, attempts int default 0,
            delivered int default 0, error text)""")
        try:
            con.execute("alter table runs add column eval_loss real")
        except sqlite3.OperationalError:
            pass
        con.execute("update runs set status='stopped' where status='running'")
        con.execute("update jobs set status='canceled' where status in ('queued','running')")
    con.close()


def run_insert(cfg, status):
    safe = {k: v for k, v in cfg.items() if k != "_job"}
    safe = {**safe, "model": {"id": cfg["model"]["id"], "token": ""}}
    con = dbcon()
    with con:
        cur = con.execute(
            "insert into runs(ts, model, samples, status, cfg) values(?,?,?,?,?)",
            (datetime.now().isoformat(timespec="seconds"), cfg["model"]["id"],
             cfg["samples"], status, json.dumps(safe, ensure_ascii=False)))
    rid = cur.lastrowid
    con.close()
    return rid


def run_finish(rid, status, loss, dur, out_dir, eval_loss=None):
    con = dbcon()
    with con:
        con.execute("update runs set status=?, loss=?, dur=?, out_dir=?, eval_loss=? "
                    "where id=?", (status, loss, dur, out_dir, eval_loss, rid))
    con.close()


def run_row(rid):
    con = dbcon()
    row = con.execute("select * from runs where id=?", (rid,)).fetchone()
    con.close()
    return row


def job_row(jid):
    con = dbcon()
    row = con.execute("select * from jobs where id=?", (jid,)).fetchone()
    con.close()
    return row


def job_update(jid, **kw):
    if not kw:
        return
    cols = ", ".join("%s=?" % k for k in kw)
    con = dbcon()
    with con:
        con.execute("update jobs set %s where id=?" % cols, (*kw.values(), jid))
    con.close()


def job_insert(cfg, webhook="", headers=None):
    clean = {k: v for k, v in cfg.items() if k != "_job"}
    con = dbcon()
    with con:
        cur = con.execute(
            "insert into jobs(ts, cfg, status, webhook, headers) values(?,?,?,?,?)",
            (datetime.now().isoformat(timespec="seconds"),
             json.dumps(clean, ensure_ascii=False), "queued", webhook or "",
             json.dumps(headers or {}, ensure_ascii=False)))
    jid = cur.lastrowid
    con.close()
    return jid


def queued_jobs():
    con = dbcon()
    rows = con.execute("select id, ts, cfg, status, webhook, headers from jobs "
                       "where status='queued' order by id").fetchall()
    con.close()
    return rows


