def mirror_from_db():
    con = dbcon()
    row = con.execute("select v from settings where k = 'mirror'").fetchone()
    con.close()
    return bool(row and row["v"] in ("1", "True", "true"))


def explain_error(e):
    s = str(e) or ""
    low = s.lower() + " " + type(e).__name__.lower()
    if ("401" in s or "403" in s or "gated" in low or "unauthorized" in low
            or "permission" in low or "don't have access" in low):
        return ("gated or private model: open its page on huggingface.co, accept "
                "the license, then paste a token (hf_...) into the Model block")
    if "404" in s or "not found" in low or "no such" in low:
        return "model id not found - check the org/name spelling in the Model block"
    if ("connection" in low or "timeout" in low or "timed out" in low
            or "network" in low or "resolve" in low or "unreachable" in low
            or "refused" in low or "reset by peer" in low):
        return ("cannot reach huggingface.co - check the internet, or tick "
                "'HF mirror' in the Model block")
    if "out of memory" in low or ("cuda" in low and "memory" in low):
        return ("gpu ran out of memory - pick a smaller model or lower batch size "
                "and max seq length")
    if "disk" in low:
        return "not enough disk space for this model"
    if "keyword argument" in low:
        return ("library version mismatch - pip install -U transformers peft "
                "accelerate, then restart")
    return ""


def parse_samples(text):
    out = []
    for ln in text.splitlines():
        ln = ln.strip()
        if not ln:
            continue
        if ln.startswith("{"):
            try:
                d = json.loads(ln)
                if isinstance(d, dict):
                    if isinstance(d.get("messages"), list) and d["messages"]:
                        msgs = []
                        for m in d["messages"]:
                            if isinstance(m, dict) and str(m.get("content", "")).strip():
                                msgs.append({"role": str(m.get("role") or "user"),
                                             "content": str(m.get("content"))})
                        if msgs:
                            out.append({"kind": "chat", "messages": msgs})
                            continue
                    if d.get("prompt") is not None and d.get("completion") is not None:
                        pr, cp = str(d["prompt"]), str(d["completion"])
                        if (pr + cp).strip():
                            out.append({"kind": "pc", "prompt": pr, "completion": cp})
                            continue
                    if isinstance(d.get("text"), str) and d["text"].strip():
                        out.append({"kind": "text", "text": d["text"].strip()})
                        continue
            except json.JSONDecodeError:
                pass
        out.append({"kind": "text", "text": ln})
    return out


def sample_text(s):
    if s["kind"] == "chat":
        return " / ".join((m["role"] + ": " + m["content"]) for m in s["messages"])
    if s["kind"] == "pc":
        return s["prompt"] + s["completion"]
    return s["text"]


def store_dataset(text):
    did = uuid.uuid4().hex[:12]
    (DATA_DIR / (did + ".txt")).write_text(text, encoding="utf-8")
    samples = parse_samples(text)
    preview = " / ".join(sample_text(s)[:70] for s in samples[:2])
    return {"id": did, "samples": len(samples), "preview": preview}


FA_CHARS = "\u067e\u0686\u0698\u06af\u06cc\u06a9"
FA_WORDS = {"و", "است", "این", "که", "را", "های", "می", "شد", "نه", "بر",
            "برای", "هست", "بود", "او", "ما", "شما", "آن", "چه", "هر", "خود"}
EN_WORDS = {"the", "is", "are", "and", "you", "that", "this", "it", "for",
            "with", "was", "have", "not", "but", "what", "how", "why"}
AR_WORDS = {"في", "من", "على", "هذا", "ذلك", "التي", "الذي", "إلى", "عن"}


def _script_counts(s):
    c = {"arabic": 0, "latin": 0, "cyr": 0, "cjk": 0, "deva": 0, "kana": 0}
    for ch in s:
        o = ord(ch)
        if 0x0600 <= o <= 0x06FF or 0x0750 <= o <= 0x077F or 0xFB50 <= o <= 0xFEFF:
            c["arabic"] += 1
        elif ch.isascii() and ch.isalpha():
            c["latin"] += 1
        elif 0x0400 <= o <= 0x04FF:
            c["cyr"] += 1
        elif 0x4E00 <= o <= 0x9FFF:
            c["cjk"] += 1
        elif 0x0900 <= o <= 0x097F:
            c["deva"] += 1
        elif 0x3040 <= o <= 0x30FF:
            c["kana"] += 1
    return c


def detect_lang(s):
    s = s.strip()
    if not s:
        return "und"
    c = _script_counts(s)
    n = max(1, len(s))
    if c["kana"] > n * 0.15:
        return "ja"
    if c["cjk"] > n * 0.2:
        return "zh"
    if c["deva"] > n * 0.2:
        return "hi"
    if c["cyr"] > n * 0.2:
        return "ru"
    if c["arabic"] > n * 0.2:
        if any(ch in s for ch in FA_CHARS) or \
                any(w in FA_WORDS for w in re.split(r"[\s\u200c]+", s)):
            return "fa"
        if any(w in AR_WORDS for w in s.split()):
            return "ar"
        return "fa" if any(ch in s for ch in FA_CHARS) else "ar"
    if c["latin"] > n * 0.2:
        words = [w.lower() for w in re.split(r"\W+", s) if w]
        if any(w in EN_WORDS for w in words):
            return "en"
        try:
            from langdetect import detect
            return detect(s)
        except Exception:
            return "en"
    return "und"


def analyze_dataset(text):
    samples = parse_samples(text)
    n = len(samples)
    kinds = Counter(s["kind"] for s in samples)
    report = {"samples": n, "kinds": dict(kinds), "warnings": [],
              "languages": {}, "parse_errors": 0}
    if not n:
        report["warnings"].append({"level": "err", "msg": "dataset is empty"})
        return report

    bad_json = 0
    for ln in text.splitlines():
        ln = ln.strip()
        if ln.startswith("{"):
            try:
                json.loads(ln)
            except json.JSONDecodeError:
                bad_json += 1
    report["parse_errors"] = bad_json

    seen, dups = {}, 0
    dup_examples = []
    for s in samples:
        key = re.sub(r"\s+", " ", sample_text(s).lower()).strip()
        seen[key] = seen.get(key, 0) + 1
    for k, cnt in seen.items():
        if cnt > 1:
            dups += cnt - 1
            if len(dup_examples) < 3:
                dup_examples.append({"count": cnt, "text": k[:90]})
    report["duplicates"] = dups
    report["dup_ratio"] = round(dups / n, 3)
    report["dup_examples"] = dup_examples
    if dups:
        lvl = "err" if dups / n > 0.2 else "warn"
        report["warnings"].append({
            "level": lvl, "msg": "%d duplicate samples (%.0f%%) - "
            "deduplicate for a cleaner eval split" % (dups, 100 * dups / n)})

    lens = [len(sample_text(s)) for s in samples]
    slens = sorted(lens)
    tok = [max(1, round(l / 3.5)) for l in lens]
    stok = sorted(tok)

    def pct(a, p):
        i = min(len(a) - 1, max(0, int(round(p / 100 * (len(a) - 1)))))
        return a[i]

    report["lengths"] = {
        "min": slens[0], "mean": round(sum(lens) / n, 1),
        "median": pct(slens, 50), "p90": pct(slens, 90), "max": slens[-1],
        "tokens_mean": round(sum(tok) / n), "tokens_p90": pct(stok, 90),
        "tokens_total": sum(tok)}
    bins = 12
    lo, hi = slens[0], slens[-1]
    span = max(1, hi - lo)
    hist = [0] * bins
    for l in lens:
        hist[min(bins - 1, int((l - lo) * bins / span))] += 1
    report["histogram"] = {"bins": bins, "lo": lo, "hi": hi, "counts": hist}

    tiny = sum(1 for l in lens if l < 12)
    huge = sum(1 for l in lens if l > 6000)
    if tiny:
        report["warnings"].append({"level": "warn", "msg":
            "%d samples shorter than 12 chars - likely noise" % tiny})
    if huge:
        report["warnings"].append({"level": "warn", "msg":
            "%d samples longer than 6000 chars - will be truncated by max seq "
            "length" % huge})
    if n < 8:
        report["warnings"].append({"level": "warn", "msg":
            "only %d samples - training and the eval split will be noisy" % n})
    if report["lengths"]["tokens_mean"] < 8:
        report["warnings"].append({"level": "warn", "msg":
            "average sample is under ~8 tokens - data may be too thin"})
    if kinds.get("text", 0) == n:
        report["warnings"].append({"level": "info", "msg":
            "no structured samples found - loss masking needs JSONL "
            '{"messages": [...]} or {"prompt","completion"} lines'})
    if bad_json:
        report["warnings"].append({"level": "err", "msg":
            "%d lines look like JSON but fail to parse" % bad_json})

    langs = Counter(detect_lang(sample_text(s)) for s in samples)
    report["languages"] = dict(langs.most_common())
    top = langs.most_common(1)[0]
    if top[0] != "und" and top[1] < n * 0.85 and len(langs) > 1:
        report["warnings"].append({"level": "warn", "msg":
            "mixed languages: " + ", ".join("%s %d" % (k, v)
                                            for k, v in langs.most_common(4))})
    return report


def _num(x, d=0.0):
    try:
        return float(x)
    except (TypeError, ValueError):
        return d


def estimate_run(cfg):
    m, lp, hp = cfg.get("model") or {}, cfg.get("lora") or {}, cfg.get("params") or {}
    mid = (m.get("custom") or "").strip() or (m.get("preset") or "").strip()
    params_b = MODEL_PARAMS.get(mid)
    note = ""
    if params_b is None:
        params_b = 7.0
        note = "unknown model size - assumed 7B for the estimate"
    ds = cfg.get("dataset_report") or {}
    samples = int(ds.get("samples") or cfg.get("samples") or 0)
    tok_total = int(ds.get("lengths", {}).get("tokens_total") or 0)
    tok_mean = int(ds.get("lengths", {}).get("tokens_mean") or 0)
    if not tok_total and samples:
        tok_mean = max(1, round(_num(hp.get("maxlen"), 1024) and 0 +
                                (ds.get("lengths", {}).get("mean") or 250) / 3.5))
        tok_total = tok_mean * samples
    epochs = _num(hp.get("epochs"), 1) or 1
    bs = int(_num(hp.get("bs"), 1) or 1)
    gacc = int(_num(hp.get("gacc"), 8) or 8)
    maxlen = int(_num(hp.get("maxlen"), 1024) or 1024)
    train_n = max(1, samples - max(0, int(samples * _num(hp.get("eval_pct"), 10) / 100)))
    steps = max(1, math.ceil(train_n / (bs * gacc)) * max(1, round(epochs)))
    seen = min(tok_mean or maxlen, maxlen) * samples * epochs if samples else 0
    if not seen and tok_total:
        seen = min(tok_total, maxlen * samples) * epochs

    size_gb = next((s for i, nm, s, p in MODELS if i == mid), None)
    load_s = 120 + (float(re.sub(r"[^0-9.]", "", size_gb) or 4) / 0.035
                    if size_gb else 240)

    gpus = []
    for name, vram, rate, ref_tps in GPUS:
        tps = ref_tps * (7.0 / max(0.1, params_b)) ** 0.8
        tps = min(tps, ref_tps * 8)
        if lp.get("qlora"):
            tps *= 0.75
        if hp.get("gc", True):
            tps *= 0.85
        train_s = (seen / tps) if tps else 0
        total_s = train_s + load_s
        gpus.append({"gpu": name, "vram": vram, "rate": rate,
                     "tps": int(tps), "minutes": round(total_s / 60),
                     "cost": round(total_s / 3600 * rate, 2),
                     "fits": vram >= (params_b * (0.6 if lp.get("qlora") else 2.0))})
    return {"model": mid, "params_b": params_b, "samples": samples,
            "tokens": int(seen), "steps": steps, "epochs": epochs,
            "gpus": gpus, "note": note or "rough estimate, expect +-50%",
            "download_hint": size_gb or "?"}


