_LAYER_RE = re.compile(r"^model\.layers\.(\d+)\.(.+)$")


def map_tensor_name(k, arch):
    if k in TENSOR_MAP:
        return TENSOR_MAP[k]
    m = _LAYER_RE.match(k)
    if m:
        lm = LAYER_MAP_GEMMA2 if arch in ("gemma2", "gemma3") else LAYER_MAP_LLAMA
        suf = lm.get(m.group(2))
        if suf:
            if suf.endswith(".bias"):
                return "blk.%s.%s" % (m.group(1), suf)
            return "blk.%s.%s.weight" % (m.group(1), suf)
    return None


def _ustruct():
    import struct
    return struct


def _q8_0_encode(arr):
    import numpy as np
    flat = arr.reshape(-1, 32)
    out = []
    CH = 65536
    for s in range(0, flat.shape[0], CH):
        blk32 = flat[s:s + CH]
        amax = np.abs(blk32).max(axis=1, keepdims=True)
        d = (amax / 127.0).astype(np.float16)
        dd = np.where(amax == 0, 1.0, amax / 127.0).astype(np.float32)
        q = np.clip(np.rint(blk32 / dd), -127, 127).astype(np.int8)
        blk = np.zeros((blk32.shape[0], 34), dtype=np.uint8)
        blk[:, :2] = d.view(np.uint8)
        blk[:, 2:] = q.view(np.uint8)
        out.append(blk.tobytes())
    return b"".join(out)


def gguf_pack_string(s):
    st = _ustruct()
    b = s.encode("utf-8")
    return st.pack("<Q", len(b)) + b


def gguf_pack_kv(key, typ, val):
    st = _ustruct()
    out = gguf_pack_string(key) + st.pack("<I", typ)
    if typ == KV_U32:
        out += st.pack("<I", int(val))
    elif typ == KV_F32:
        out += st.pack("<f", float(val))
    elif typ == KV_U64:
        out += st.pack("<Q", int(val))
    elif typ == KV_BOOL:
        out += st.pack("<B", 1 if val else 0)
    elif typ == KV_STR:
        out += gguf_pack_string(str(val))
    elif typ == KV_ARR:
        ityp, items = val
        out += st.pack("<I", ityp) + st.pack("<Q", len(items))
        for it in items:
            if ityp == KV_STR:
                out += gguf_pack_string(str(it))
            elif ityp == KV_U32:
                out += st.pack("<I", int(it))
            elif ityp == KV_I32:
                out += st.pack("<i", int(it))
            elif ityp == KV_F32:
                out += st.pack("<f", float(it))
            else:
                raise ValueError("array item type %d not supported" % ityp)
    else:
        raise ValueError("kv type %d not supported" % typ)
    return out


def gguf_vocab(tok, src_dir):
    import json as _json
    tj_path = Path(src_dir) / "tokenizer.json"
    if not tj_path.exists():
        return None
    tj = _json.loads(tj_path.read_text(encoding="utf-8"))
    model = tj.get("model") or {}
    vocab = model.get("vocab") or {}
    merges = model.get("merges") or []
    if not vocab:
        return None
    added = {int(a["id"]): a for a in tj.get("added_tokens", [])}
    max_id = max(list(vocab.values()) + list(added.keys()))
    inv = {v: k for k, v in vocab.items()}
    tokens, types, scores = [], [], []
    for i in range(max_id + 1):
        if i in added:
            tokens.append(added[i]["content"])
            types.append(3 if added[i].get("special") else 4)
            scores.append(0.0)
            continue
        s = inv.get(i, "")
        tokens.append(s)
        if re.fullmatch(r"<0x[0-9A-Fa-f]{2}>", s):
            types.append(6)
        else:
            types.append(1)
        scores.append(0.0)
    merge_strs = []
    for m in merges:
        if isinstance(m, str):
            merge_strs.append(m)
        elif isinstance(m, list) and len(m) == 2:
            merge_strs.append(m[0] + " " + m[1])
        elif isinstance(m, dict):
            merge_strs.append(m.get("l", "") + " " + m.get("r", ""))
    tok_model = "gpt2" if model.get("type", "BPE").upper() == "BPE" else str(model.get("type", "gpt2")).lower()
    out = {
        "model": tok_model, "tokens": tokens, "types": types,
        "scores": scores, "merges": merge_strs,
        "bos": getattr(tok, "bos_token_id", None),
        "eos": getattr(tok, "eos_token_id", None),
    }
    return out


def gguf_convert(src_dir, out_path, quant="f16", tok=None, say=lambda m: None):
    import numpy as np
    import torch

    src_dir = Path(src_dir)
    cfg = json.loads((src_dir / "config.json").read_text(encoding="utf-8"))
    mtype = (cfg.get("model_type") or "").lower()
    arch = ARCH_MAP.get(mtype)
    if arch is None:
        say("model_type %r not in the built-in map, trying llama layout" % mtype)
        arch = "llama"
    hidden = cfg["hidden_size"]
    heads = cfg["num_attention_heads"]
    kv_heads = cfg.get("num_key_value_heads") or heads
    head_dim = cfg.get("head_dim") or hidden // heads
    inter = cfg["intermediate_size"]
    nlayers = cfg["num_hidden_layers"]
    eps = cfg.get("rms_norm_eps", 1e-6)
    rope_base = cfg.get("rope_theta", 10000.0)
    tie = cfg.get("tie_word_embeddings", False)

    shards = sorted(src_dir.glob("*.safetensors"))
    if not shards:
        raise RuntimeError("no safetensors found in " + str(src_dir))
    from safetensors import safe_open

    metas = []
    for si, sh in enumerate(shards):
        with safe_open(str(sh), framework="pt") as sf:
            for k in sf.keys():
                sl = sf.get_slice(k)
                metas.append((si, k, tuple(sl.get_shape())))

    plan = []
    dropped = []
    for si, k, shape in sorted(metas, key=lambda x: x[1]):
        name = map_tensor_name(k, arch)
        if name is None and mtype == "phi3":
            m = re.fullmatch(r"model\.layers\.(\d+)\.self_attn\.qkv_proj\.weight", k)
            if m:
                i = m.group(1)
                qend = heads * head_dim
                kend = qend + kv_heads * head_dim
                plan.append({"gguf": "blk.%s.attn_q.weight" % i, "si": si, "key": k,
                             "rows": (0, qend), "shape": (qend, shape[1])})
                plan.append({"gguf": "blk.%s.attn_k.weight" % i, "si": si, "key": k,
                             "rows": (qend, kend), "shape": (kend - qend, shape[1])})
                plan.append({"gguf": "blk.%s.attn_v.weight" % i, "si": si, "key": k,
                             "rows": (kend, kend + kv_heads * head_dim),
                             "shape": (kv_heads * head_dim, shape[1])})
                continue
            m = re.fullmatch(r"model\.layers\.(\d+)\.self_attn\.qkv_proj\.bias", k)
            if m:
                i = m.group(1)
                qend = heads * head_dim
                kend = qend + kv_heads * head_dim
                plan.append({"gguf": "blk.%s.attn_q.bias" % i, "si": si, "key": k,
                             "rows": (0, qend), "shape": (qend,)})
                plan.append({"gguf": "blk.%s.attn_k.bias" % i, "si": si, "key": k,
                             "rows": (qend, kend), "shape": (kend - qend,)})
                plan.append({"gguf": "blk.%s.attn_v.bias" % i, "si": si, "key": k,
                             "rows": (kend, kend + kv_heads * head_dim),
                             "shape": (kv_heads * head_dim,)})
                continue
            m = re.fullmatch(r"model\.layers\.(\d+)\.mlp\.gate_up_proj\.weight", k)
            if m:
                i = m.group(1)
                plan.append({"gguf": "blk.%s.ffn_gate.weight" % i, "si": si, "key": k,
                             "rows": (0, inter), "shape": (inter, shape[1])})
                plan.append({"gguf": "blk.%s.ffn_up.weight" % i, "si": si, "key": k,
                             "rows": (inter, 2 * inter), "shape": (inter, shape[1])})
                continue
        if name is None:
            if k == "lm_head.weight" and tie:
                continue
            dropped.append(k)
            continue
        if name == "output.weight" and tie:
            continue
        plan.append({"gguf": name, "si": si, "key": k, "rows": None, "shape": shape})
    if dropped:
        say("skipped unmapped tensors: " + ", ".join(dropped[:6]))

    def tsize(numel, gt):
        if gt == GT_Q8_0:
            return (numel // 32) * 34
        if gt == GT_F16:
            return numel * 2
        return numel * 4

    for p in plan:
        row = int(p["shape"][-1])
        numel = p["shape"][0] * row if len(p["shape"]) > 1 else row
        if len(p["shape"]) == 1:
            # llama.cpp convention: 1-D tensors (norms, biases) are always
            # stored as f32; f16/f32-quantized weights multiply f32
            # activations and ggml does not support mixed f32 x f16 muls
            p["gt"] = GT_F32
        elif quant == "q8_0" and (row % 32 or numel % 32):
            say("%s row %d not multiple of 32, keeping f16" % (p["gguf"], row))
            p["gt"] = GT_F16
        else:
            p["gt"] = {"f32": GT_F32, "f16": GT_F16, "q8_0": GT_Q8_0}[quant]
        p["nbytes"] = tsize(numel, p["gt"])

    vinfo = None
    if tok is not None:
        vinfo = gguf_vocab(tok, src_dir)
    # pad tokenizer arrays to the model's full vocab_size (llama.cpp requires
    # the tokens array to cover every embedding row; HF pads e.g. Qwen2.5
    # 151665 -> 151936)
    _vs = int(cfg.get("vocab_size", 0))
    if vinfo and _vs > len(vinfo["tokens"]):
        for _i in range(len(vinfo["tokens"]), _vs):
            vinfo["tokens"].append("[PAD%d]" % _i)
            vinfo["types"].append(4)   # UNUSED per llama.cpp TokenType
            vinfo["scores"].append(0.0)
    if vinfo is None:
        say("no tokenizer.json found - writing without vocab (llama.cpp "
            "will not load this; use it for pipeline checks only)")

    st = _ustruct()
    kvs = []
    kvs.append(("general.architecture", KV_STR, arch))
    kvs.append(("general.name", KV_STR, cfg.get("_name_or_path", arch) or arch))
    kvs.append(("general.file_type", KV_U32, FTYPE.get(quant, 1)))
    if vinfo:
        kvs.append(("tokenizer.ggml.model", KV_STR, vinfo["model"]))
        kvs.append(("tokenizer.ggml.tokens", KV_ARR, (KV_STR, vinfo["tokens"])))
        kvs.append(("tokenizer.ggml.token_type", KV_ARR, (KV_I32, vinfo["types"])))
        kvs.append(("tokenizer.ggml.scores", KV_ARR, (KV_F32, vinfo["scores"])))
        if vinfo["merges"]:
            kvs.append(("tokenizer.ggml.merges", KV_ARR, (KV_STR, vinfo["merges"])))
        if vinfo.get("bos") is not None:
            kvs.append(("tokenizer.ggml.bos_token_id", KV_U32, vinfo["bos"]))
        if vinfo.get("eos") is not None:
            kvs.append(("tokenizer.ggml.eos_token_id", KV_U32, vinfo["eos"]))
        kvs.append(("tokenizer.ggml.add_bos_token", KV_BOOL,
                    bool(vinfo.get("bos") is not None and arch in ("llama", "phi3"))))
        kvs.append(("tokenizer.ggml.add_eos_token", KV_BOOL, False))
        tmpl = None
        ctpl = Path(src_dir) / "chat_template.jinja"
        if ctpl.exists():
            tmpl = ctpl.read_text(encoding="utf-8")
        elif tok is not None and getattr(tok, "chat_template", None):
            tmpl = tok.chat_template
        if tmpl:
            kvs.append(("tokenizer.chat_template", KV_STR, tmpl))
    p = arch
    kvs.append((p + ".vocab_size", KV_U32, int(cfg.get("vocab_size",
                 len(vinfo["tokens"]) if vinfo else 0))))
    kvs.append((p + ".context_length", KV_U32, cfg.get("max_position_embeddings", 4096)))
    kvs.append((p + ".embedding_length", KV_U32, hidden))
    kvs.append((p + ".block_count", KV_U32, nlayers))
    kvs.append((p + ".feed_forward_length", KV_U32, inter))
    kvs.append((p + ".attention.head_count", KV_U32, heads))
    kvs.append((p + ".attention.head_count_kv", KV_U32, kv_heads))
    kvs.append((p + ".attention.key_length", KV_U32, head_dim))
    kvs.append((p + ".attention.layer_norm_rms_epsilon", KV_F32, float(eps)))
    kvs.append((p + ".rope.freq_base", KV_F32, float(rope_base)))
    if arch == "gemma2":
        sc = cfg.get("attn_logit_softcapping")
        fsc = cfg.get("final_logit_softcapping")
        if sc is not None:
            kvs.append(("gemma2.attention.logit_softcapping", KV_F32, float(sc)))
        if fsc is not None:
            kvs.append(("gemma2.final_logit_softcapping", KV_F32, float(fsc)))

    with open(out_path, "wb") as f:
        f.write(GGUF_MAGIC)
        f.write(st.pack("<I", 3))
        f.write(st.pack("<Q", len(plan)))
        f.write(st.pack("<Q", len(kvs)))
        for k, t, v in kvs:
            f.write(gguf_pack_kv(k, t, v))
        offset = 0
        for p in plan:
            p["off"] = offset
            offset += p["nbytes"]
            offset += (ALIGN - offset % ALIGN) % ALIGN
        for p in plan:
            ne = list(p["shape"])[::-1]
            f.write(gguf_pack_string(p["gguf"]))
            f.write(st.pack("<I", len(ne)))
            for d in ne:
                f.write(st.pack("<Q", int(d)))
            f.write(st.pack("<I", p["gt"]))
            f.write(st.pack("<Q", p["off"]))
        cur = f.tell()
        f.write(b"\x00" * ((ALIGN - cur % ALIGN) % ALIGN))
        handles = [safe_open(str(sh), framework="pt") for sh in shards]
        try:
            for idx, p in enumerate(plan):
                w = handles[p["si"]].get_tensor(p["key"])
                if p["rows"]:
                    a, b = p["rows"]
                    w = w[a:b]
                arr = w.to(torch.float32).numpy()
                del w
                if p["gt"] == GT_Q8_0:
                    data = _q8_0_encode(arr)
                elif p["gt"] == GT_F16:
                    data = arr.astype(np.float16).tobytes()
                else:
                    data = arr.astype(np.float32).tobytes()
                del arr
                f.write(data)
                if idx < len(plan) - 1:
                    f.write(b"\x00" * ((ALIGN - len(data) % ALIGN) % ALIGN))
        finally:
            for h in handles:
                h.close() if hasattr(h, "close") else None

    size_mb = Path(out_path).stat().st_size / 1e6
    say("gguf written: %s (%.1f MB, %d tensors, arch %s, %s)" %
        (out_path, size_mb, len(plan), arch, quant))
    return str(out_path), {"tensors": len(plan), "arch": arch, "quant": quant,
                           "size_mb": round(size_mb, 1)}


def gguf_inspect(path):
    st = _ustruct()
    with open(path, "rb") as f:
        data = f.read()
    if data[:4] != GGUF_MAGIC:
        raise ValueError("not a gguf file")
    ver = st.unpack("<I", data[4:8])[0]
    ntens = st.unpack("<Q", data[8:16])[0]
    nkv = st.unpack("<Q", data[16:24])[0]
    pos = 24

    def rd_str(p):
        n = st.unpack("<Q", data[p:p + 8])[0]
        return data[p + 8:p + 8 + n].decode("utf-8"), p + 8 + n

    def rd_val(p, t):
        fmt = {1: "<b", 2: "<H", 3: "<h", 4: "<I", 5: "<i", 6: "<f",
               10: "<q", 12: "<d"}
        if t in fmt:
            sz = st.calcsize(fmt[t])
            return st.unpack(fmt[t], data[p:p + sz])[0], p + sz
        if t == 0:
            return data[p], p + 1
        if t == KV_BOOL:
            return bool(data[p]), p + 1
        if t == KV_STR:
            return rd_str(p)
        if t == KV_ARR:
            it, p = st.unpack("<I", data[p:p + 4])[0], p + 4
            cnt = st.unpack("<Q", data[p:p + 8])[0]
            p += 8
            out = []
            for _ in range(cnt):
                v, p = rd_val(p, it)
                out.append(v)
            return out, p
        raise ValueError("kv type %d" % t)

    kvs = {}
    for _ in range(nkv):
        key, pos = rd_str(pos)
        t = st.unpack("<I", data[pos:pos + 4])[0]
        pos += 4
        v, pos = rd_val(pos, t)
        kvs[key] = v
    tensors = []
    for _ in range(ntens):
        name, pos = rd_str(pos)
        nd = st.unpack("<I", data[pos:pos + 4])[0]
        pos += 4
        dims = []
        for _ in range(nd):
            dims.append(st.unpack("<Q", data[pos:pos + 8])[0])
            pos += 8
        gt = st.unpack("<I", data[pos:pos + 4])[0]
        pos += 4
        off = st.unpack("<Q", data[pos:pos + 8])[0]
        pos += 8
        tensors.append({"name": name, "dims": dims, "type": gt, "offset": off})
    return {"version": ver, "kv_count": nkv, "kvs": kvs, "tensors": tensors,
            "size": len(data)}


def gguf_tensor_bytes(path, name):
    import numpy as np
    info = gguf_inspect(path)
    t = next(x for x in info["tensors"] if x["name"] == name)
    st = _ustruct()
    with open(path, "rb") as f:
        raw = f.read()
    pos = 24

    def rd_str(p):
        n = st.unpack("<Q", raw[p:p + 8])[0]
        return raw[p + 8:p + 8 + n].decode("utf-8"), p + 8 + n
    for _ in range(info["kv_count"]):
        _, pos = rd_str(pos)
        t_ = st.unpack("<I", raw[pos:pos + 4])[0]
        pos += 4
        if t_ == KV_STR:
            _, pos = rd_str(pos)
        elif t_ in (0, 1, 7):
            pos += 1
        elif t_ in (2, 3):
            pos += 2
        elif t_ in (4, 5, 6):
            pos += 4
        elif t_ in (10, 11, 12):
            pos += 8
        elif t_ == KV_ARR:
            it = st.unpack("<I", raw[pos:pos + 4])[0]
            cnt = st.unpack("<Q", raw[pos + 4:pos + 12])[0]
            pos += 12
            if it == KV_STR:
                for _ in range(cnt):
                    _, pos = rd_str(pos)
            elif it in (0, 1, 7):
                pos += cnt
            elif it in (2, 3):
                pos += cnt * 2
            elif it in (4, 5, 6):
                pos += cnt * 4
            elif it in (10, 11, 12):
                pos += cnt * 8
            else:
                raise ValueError("array item type %d" % it)
    for _ in range(len(info["tensors"])):
        nm, pos = rd_str(pos)
        nd = st.unpack("<I", raw[pos:pos + 4])[0]
        pos += 4 + 8 * nd + 4 + 8
    data_start = pos + (ALIGN - pos % ALIGN) % ALIGN
    numel = int(np.prod(t["dims"]))
    off = data_start + t["offset"]
    if t["type"] == GT_F16:
        return np.frombuffer(raw, dtype="<f2", count=numel, offset=off).astype(np.float32)
    if t["type"] == GT_F32:
        return np.frombuffer(raw, dtype="<f4", count=numel, offset=off).copy()
    if t["type"] == GT_Q8_0:
        nb = numel // 32
        blocks = np.frombuffer(raw, dtype=np.uint8, count=nb * 34, offset=off)
        blocks = blocks.reshape(nb, 34)
        d = blocks[:, :2].copy().view("<f2").astype(np.float32).reshape(nb, 1)
        q = blocks[:, 2:].copy().view(np.int8).astype(np.float32)
        return (d * q).reshape(-1)
    raise ValueError("type %d not dequantizable" % t["type"])


def find_llama_quantize():
    p = os.environ.get("TT_LLAMA_CPP", "").strip()
    if p:
        cand = [Path(p) / "llama-quantize", Path(p) / "build" / "bin" / "llama-quantize"]
        for c in cand:
            if c.exists():
                return str(c)
    from shutil import which
    w = which("llama-quantize")
    return w


def assistant_spans(tok, messages, final):
    spans = []
    try:
        for i, m in enumerate(messages):
            if m["role"] != "assistant":
                continue
            if i == 0:
                try:
                    before = tok.apply_chat_template(
                        [], tokenize=False, add_generation_prompt=True) or ""
                except Exception:
                    before = ""
            else:
                before = tok.apply_chat_template(
                    messages[:i], tokenize=False, add_generation_prompt=True) or ""
            after = tok.apply_chat_template(messages[:i + 1], tokenize=False) or ""
            if final.startswith(before) and final.startswith(after) \
                    and len(before) <= len(after):
                spans.append((len(before), len(after)))
            else:
                return []
    except Exception:
        return []
    return spans


def build_features(tok, samples, maxlen, mask):
    feats, n_masked, n_plain = [], 0, 0
    for s in samples:
        if s["kind"] == "chat":
            try:
                final = tok.apply_chat_template(s["messages"], tokenize=False)
            except Exception:
                final = None
            if final is None:
                raw = "\n".join(m["role"] + ": " + m["content"] for m in s["messages"])
                ids = tok(raw, truncation=True, max_length=maxlen)["input_ids"]
                feats.append({"input_ids": ids, "labels": list(ids)})
                n_plain += 1
                continue
            enc = tok(final, truncation=True, max_length=maxlen,
                      add_special_tokens=False, return_offsets_mapping=True)
            ids, offs = enc["input_ids"], enc["offset_mapping"]
            labels = list(ids)
            if mask:
                spans = assistant_spans(tok, s["messages"], final)
                if spans:
                    labels = [-100] * len(ids)
                    for ti, (ca, cb) in enumerate(offs):
                        mid = (ca + cb) / 2
                        for a, b in spans:
                            if a <= mid < b:
                                labels[ti] = ids[ti]
                                break
                    n_masked += 1
                else:
                    n_plain += 1
            feats.append({"input_ids": ids, "labels": labels})
        elif s["kind"] == "pc":
            final = s["prompt"] + s["completion"]
            enc = tok(final, truncation=True, max_length=maxlen,
                      add_special_tokens=False, return_offsets_mapping=True)
            ids, offs = enc["input_ids"], enc["offset_mapping"]
            labels = list(ids)
            if mask:
                cut = len(s["prompt"])
                labels = [-100 if (ca + cb) / 2 < cut else ids[ti]
                          for ti, (ca, cb) in enumerate(offs)]
                n_masked += 1
            feats.append({"input_ids": ids, "labels": labels})
        else:
            ids = tok(s["text"], truncation=True, max_length=maxlen)["input_ids"]
            feats.append({"input_ids": ids, "labels": list(ids)})
            n_plain += 1
    return feats, n_masked, n_plain


def split_eval(feats, pct, seed):
    if pct <= 0 or len(feats) < 8:
        return feats, []
    n_eval = int(len(feats) * pct / 100)
    if n_eval < 2 or len(feats) - n_eval < 2:
        return feats, []
    rng = random.Random(int(seed))
    idx = list(range(len(feats)))
    rng.shuffle(idx)
    ev = [feats[i] for i in idx[:n_eval]]
    tr = [feats[i] for i in idx[n_eval:]]
    return tr, ev


def pad_collate(tok):
    import torch

    def collate(batch):
        ml = max(len(b["input_ids"]) for b in batch)
        pad = tok.pad_token_id if tok.pad_token_id is not None else (tok.eos_token_id or 0)
        ii, am, ll = [], [], []
        for b in batch:
            n = len(b["input_ids"])
            ii.append(list(b["input_ids"]) + [pad] * (ml - n))
            am.append([1] * n + [0] * (ml - n))
            ll.append(list(b["labels"]) + [-100] * (ml - n))
        return {"input_ids": torch.tensor(ii),
                "attention_mask": torch.tensor(am),
                "labels": torch.tensor(ll)}
    return collate


def latest_checkpoint(run_dir):
    tr = Path(run_dir) / "trainer"
    if not tr.exists():
        return None
    cks = [p for p in tr.glob("checkpoint-*") if p.is_dir()]
    if not cks:
        return None
    return str(max(cks, key=lambda p: int(p.name.split("-")[-1])))


class Engine:
    def __init__(self):
        self.lock = threading.Lock()
        self.stop_flag = threading.Event()
        self.st = self.blank()

    def blank(self):
        return dict(phase="idle", run_id=None, model="", samples=0, step=0, total=0,
                    losses=[], val_losses=[], log=[], error="", out_dir="",
                    started=0, elapsed=0, job_id=None, masked=0, plain=0,
                    eval_n=0, early_stop=False, resumed="")

    @property
    def busy(self):
        with self.lock:
            return self.st["phase"] in ("loading", "training", "saving")

    def status(self):
        with self.lock:
            s = dict(self.st)
        if s["started"]:
            s["elapsed"] = int(time.time() - s["started"])
        return s

    def say(self, line):
        with self.lock:
            self.st["log"].append(datetime.now().strftime("%H:%M:%S ") + line)
            del self.st["log"][:-250]

    def last_loss(self):
        with self.lock:
            return self.st["losses"][-1][1] if self.st["losses"] else None

    def best_eval(self):
        with self.lock:
            return min((v[1] for v in self.st["val_losses"]), default=None)

    def start(self, cfg):
        with self.lock:
            if self.st["phase"] in ("loading", "training", "saving"):
                return False
            self.st = self.blank()
            self.st.update(phase="loading", model=cfg["model"]["id"],
                           samples=cfg["samples"], started=time.time())
            job = cfg.get("_job") or {}
            self.st["job_id"] = job.get("id")
        self.stop_flag = threading.Event()
        with self.lock:
            self.st["run_id"] = run_insert(cfg, "running")
            if cfg.get("_job"):
                job_update(cfg["_job"]["id"], run_id=self.st["run_id"])
        threading.Thread(target=self.work, args=(cfg,), daemon=True).start()
        return True

    def work(self, cfg):
        t0 = time.time()
        try:
            self.train(cfg)
            phase = "stopped" if self.stop_flag.is_set() else "done"
            with self.lock:
                self.st["phase"] = phase
                if self.st.get("early_stop"):
                    phase = "done"
            run_finish(self.st["run_id"], phase, self.last_loss(),
                       int(time.time() - t0), self.st["out_dir"], self.best_eval())
        except Stopped:
            with self.lock:
                self.st["phase"] = "stopped"
            run_finish(self.st["run_id"], "stopped", self.last_loss(),
                       int(time.time() - t0), self.st["out_dir"], self.best_eval())
            self.say("stopped")
        except Exception as e:
            hint = explain_error(e)
            self.say("error: " + str(e))
            if hint:
                self.say("hint: " + hint)
            if os.environ.get("TT_DEBUG"):
                traceback.print_exc()
            with self.lock:
                self.st["phase"] = "error"
                self.st["error"] = (hint + " | " + str(e))[:300] if hint else str(e)[:300]
            run_finish(self.st["run_id"], "error", None, int(time.time() - t0), "")
        finally:
            self.job_finish(cfg, int(time.time() - t0))
            with self.lock:
                if self.st["started"]:
                    self.st["elapsed"] = int(time.time() - self.st["started"])
                self.st["started"] = 0

    def job_finish(self, cfg, dur):
        job = cfg.get("_job")
        if not job or not job.get("id"):
            return
        jid = job["id"]
        with self.lock:
            st = dict(self.st)
        row = job_row(jid)
        status = st["phase"] if st["phase"] != "done" else "done"
        if row and row["status"] == "canceled":
            status = "canceled"
        payload = {
            "job_id": jid, "run_id": st.get("run_id"), "status": status,
            "model": cfg["model"]["id"], "samples": cfg.get("samples"),
            "steps": {"done": st.get("step"), "total": st.get("total")},
            "loss": self.last_loss(), "eval_loss": self.best_eval(),
            "early_stopped": bool(st.get("early_stop")),
            "duration_s": dur, "out_dir": st.get("out_dir"),
            "adapter_dir": (Path(st["out_dir"]) / "adapter").as_posix()
            if st.get("out_dir") else None,
            "gguf": next((str(p) for p in Path(st["out_dir"]).glob("model-*.gguf")), None)
            if st.get("out_dir") else None,
            "error": st.get("error", ""), "finished_at":
            datetime.now().isoformat(timespec="seconds")}
        job_update(jid, status=status, result=json.dumps(payload, ensure_ascii=False))
        if job.get("webhook"):
            deliver_webhook(jid, job["webhook"], job.get("headers") or {}, payload)

    def train(self, cfg):
        import torch
        import transformers
        from peft import LoraConfig, get_peft_model
        from transformers import (AutoModelForCausalLM, AutoTokenizer,
                                  Trainer, TrainerCallback, TrainingArguments)

        m, lp, hp = cfg["model"], cfg["lora"], cfg["params"]
        set_mirror(bool(m.get("mirror")))
        resume = cfg.get("resume") or {}
        if resume.get("run_dir"):
            run_dir = Path(resume["run_dir"])
            if not run_dir.exists():
                raise RuntimeError("resume dir missing: " + str(run_dir))
        else:
            run_dir = RUNS_DIR / ("run-" + datetime.now().strftime("%Y%m%d-%H%M%S"))
        run_dir.mkdir(parents=True, exist_ok=True)
        disk_cfg = {k: v for k, v in cfg.items() if k != "_job"}
        if isinstance(disk_cfg.get("model"), dict):
            disk_cfg["model"] = {**disk_cfg["model"], "token": ""}
        (run_dir / "config.json").write_text(
            json.dumps(disk_cfg, indent=2, ensure_ascii=False),
            encoding="utf-8")
        with self.lock:
            self.st["out_dir"] = str(run_dir)

        ckpt = latest_checkpoint(run_dir) if resume.get("run_dir") else None

        cuda = torch.cuda.is_available()
        bf16 = cuda and torch.cuda.is_bf16_supported()
        self.say("torch %s | transformers %s | %s" % (
            torch.__version__, transformers.__version__,
            torch.cuda.get_device_name(0) if cuda else "cpu"))
        if ckpt:
            self.say("resuming from %s" % Path(ckpt).name)
            with self.lock:
                self.st["resumed"] = Path(ckpt).name

        token = m.get("token") or None
        try:
            tok = AutoTokenizer.from_pretrained(m["id"], token=token)
        except TypeError:
            tok = AutoTokenizer.from_pretrained(m["id"], use_auth_token=token)
        if tok.pad_token is None:
            tok.pad_token = tok.eos_token

        quant = None
        if lp.get("qlora"):
            if not cuda:
                self.say("no cuda around, QLoRA off")
            else:
                from transformers import BitsAndBytesConfig
                quant = BitsAndBytesConfig(
                    load_in_4bit=True, bnb_4bit_quant_type="nf4",
                    bnb_4bit_compute_dtype=torch.bfloat16 if bf16 else torch.float16,
                    bnb_4bit_use_double_quant=True)

        self.say("loading model, first run pulls it from the hub")
        infer_srv.unload()
        _trim_ram()
        kw = dict(torch_dtype=torch.bfloat16 if bf16 else
                  (torch.float16 if cuda else torch.float32))
        if token:
            kw["token"] = token
        if quant is not None:
            kw.update(quantization_config=quant, device_map={"": 0})
        try:
            model = AutoModelForCausalLM.from_pretrained(m["id"], **kw)
        except TypeError as te:
            if "torch_dtype" not in str(te):
                raise
            kw["dtype"] = kw.pop("torch_dtype")
            model = AutoModelForCausalLM.from_pretrained(m["id"], **kw)
        if self.stop_flag.is_set():
            raise Stopped()
        model.config.use_cache = False

        mods = [TARGET_ALIASES.get(x.strip().lower(), x.strip())
                for x in (lp.get("targets") or DEFAULT_TARGETS).split(",")]
        mods = [x for x in mods if x]
        model = get_peft_model(model, LoraConfig(
            r=int(lp.get("r") or 16),
            lora_alpha=int(lp.get("alpha") or 32),
            lora_dropout=float(lp.get("dropout") or 0.05),
            target_modules=mods, task_type="CAUSAL_LM"))
        if hp.get("gc", True):
            model.enable_input_require_grads()
        n_par = sum(p.numel() for p in model.parameters() if p.requires_grad)
        self.say("trainable params %.2fM | targets: %s" % (n_par / 1e6, ", ".join(mods)))

        samples = parse_samples(Path(cfg["dataset_path"]).read_text(encoding="utf-8"))
        maxlen = int(hp.get("maxlen") or 1024)
        mask = bool(hp.get("loss_mask", True))
        feats, n_masked, n_plain = build_features(tok, samples, maxlen, mask)
        with self.lock:
            self.st["masked"] = n_masked
            self.st["plain"] = n_plain
        self.say("%d samples | max_len %d | loss-masked %d (%d plain)" %
                 (len(feats), maxlen, n_masked, n_plain))
        if mask and n_plain:
            self.say("hint: plain-text samples get no masking; JSONL with "
                     '{"messages":...} or {"prompt","completion"} enables it')

        seed = int(hp.get("seed") or 42)
        eval_pct = float(hp.get("eval_pct") or 0)
        train_feats, eval_feats = split_eval(feats, eval_pct, seed)
        patience = int(hp.get("patience") or 0)
        with self.lock:
            self.st["eval_n"] = len(eval_feats)
        if eval_feats:
            self.say("eval split: %d train / %d val (early stop %s)" %
                     (len(train_feats), len(eval_feats),
                      ("patience %d" % patience) if patience >= 1 else "off"))
        else:
            self.say("eval split off")

        class DS(torch.utils.data.Dataset):
            def __init__(self, fs):
                self.fs = fs

            def __len__(self):
                return len(self.fs)

            def __getitem__(self, i):
                return self.fs[i]

        eng = self

        class CB(TrainerCallback):
            def __init__(self):
                self.best = None
                self.bad = 0

            def on_step_end(self, args, state, control, **kw):
                with eng.lock:
                    eng.st["step"] = state.global_step
                    eng.st["total"] = state.max_steps
                if eng.stop_flag.is_set():
                    control.should_training_stop = True

            def on_log(self, args, state, control, logs=None, **kw):
                if not logs:
                    return
                if logs.get("loss") is not None:
                    with eng.lock:
                        eng.st["losses"].append([state.global_step,
                                                 float(logs["loss"])])
                if logs.get("eval_loss") is not None:
                    v = float(logs["eval_loss"])
                    with eng.lock:
                        eng.st["val_losses"].append([state.global_step, v])
                    if self.best is None or v < self.best:
                        self.best = v
                        self.bad = 0
                    else:
                        self.bad += 1
                        if patience >= 1 and self.bad >= patience:
                            with eng.lock:
                                eng.st["early_stop"] = True
                            eng.say("eval loss not improving for %d evals - "
                                    "early stopping" % patience)

        bs = int(hp.get("bs") or 1)
        gacc = int(hp.get("gacc") or 8)
        epochs = float(hp.get("epochs") or 1)
        est_steps = max(1, math.ceil(len(train_feats) / (bs * gacc)) *
                        max(1, math.ceil(epochs)))
        eval_steps = max(1, min(50, est_steps // 10 or 1))
        save_steps = eval_steps if eval_feats else max(1, min(50, est_steps // 8 or 1))

        want = dict(
            output_dir=str(run_dir / "trainer"),
            num_train_epochs=epochs,
            per_device_train_batch_size=bs,
            gradient_accumulation_steps=gacc,
            learning_rate=float(hp.get("lr") or 2e-4),
            warmup_ratio=float(hp.get("warmup") or 0.03),
            lr_scheduler_type=hp.get("sched") or "linear",
            logging_steps=1,
            save_strategy="no",
            report_to="none",
            seed=seed,
            bf16=bf16,
            fp16=cuda and not bf16,
            gradient_checkpointing=bool(hp.get("gc", True)),
            gradient_checkpointing_kwargs={"use_reentrant": False},
            remove_unused_columns=False,
        )
        want.update(save_strategy="steps", save_steps=save_steps,
                    save_total_limit=2)
        if eval_feats:
            want.update(eval_strategy="steps", eval_steps=eval_steps,
                        load_best_model_at_end=True,
                        metric_for_best_model="eval_loss", greater_is_better=False)
        sig = set(inspect.signature(TrainingArguments.__init__).parameters)
        if "eval_strategy" not in sig and "evaluation_strategy" in sig:
            want["evaluation_strategy"] = want.pop("eval_strategy", None)
        if "warmup_ratio" not in sig and "warmup_steps" in sig:
            bs_n = bs * gacc
            spe = max(1, math.ceil(len(train_feats) / bs_n))
            want["warmup_steps"] = int(round(
                want["warmup_ratio"] * spe * epochs))
        keep = {k: v for k, v in want.items() if k in sig and v is not None}
        drop = sorted(set(want) - set(keep))
        if drop:
            self.say("skipped args this transformers lacks: " + ", ".join(drop))
        args = TrainingArguments(**keep)

        callbacks = [CB()]
        if eval_feats and patience >= 1:
            try:
                from transformers import EarlyStoppingCallback
                callbacks.append(EarlyStoppingCallback(
                    early_stopping_patience=patience))
                self.say("early stopping armed (patience %d)" % patience)
            except Exception as e:
                self.say("early stopping unavailable: " + str(e)[:80])

        with self.lock:
            self.st["phase"] = "training"
        self.say("epochs %g | lr %g | bs %d x %d" % (
            args.num_train_epochs, args.learning_rate,
            args.per_device_train_batch_size, args.gradient_accumulation_steps))

        trainer = Trainer(model=model, args=args, train_dataset=DS(train_feats),
                          eval_dataset=DS(eval_feats) if eval_feats else None,
                          data_collator=pad_collate(tok), callbacks=callbacks)
        trainer.train(resume_from_checkpoint=ckpt)

        with self.lock:
            self.st["phase"] = "saving"
        adapter = run_dir / "adapter"
        model.save_pretrained(adapter)
        tok.save_pretrained(adapter)
        self.say("adapter saved: " + str(adapter))

        if cfg["output"].get("merge"):
            if quant is not None:
                self.say("merge skipped on 4-bit, keep the adapter")
            else:
                merged = model.merge_and_unload()
                merged.save_pretrained(run_dir / "merged")
                tok.save_pretrained(run_dir / "merged")
                self.say("merged model saved: " + str(run_dir / "merged"))
                del merged
                _trim_ram()

        del model
        del trainer
        if cuda:
            torch.cuda.empty_cache()
        _trim_ram()

        if cfg["output"].get("gguf"):
            try:
                gguf_export(run_dir, m["id"], token, bool(m.get("mirror")),
                            cfg["output"].get("gguf_quant") or "q8_0", self.say)
            except Exception as e:
                self.say("gguf export failed: " + str(e)[:200])

        _trim_ram()
        self.say("memory released")


engine = Engine()


class QueueRunner(threading.Thread):

    def __init__(self, eng):
        super().__init__(daemon=True)
        self.eng = eng

    def run(self):
        while True:
            time.sleep(1.0)
            try:
                self.tick()
            except Exception:
                if os.environ.get("TT_DEBUG"):
                    traceback.print_exc()
                else:
                    sys.stderr.write("[queue] tick failed: %s\n"
                                     % traceback.format_exc()[-300:])

    def tick(self):
        if self.eng.busy:
            return
        rows = queued_jobs()
        if not rows:
            return
        row = rows[0]
        jid = row["id"]
        try:
            cfg = json.loads(row["cfg"])
        except Exception:
            job_update(jid, status="error", error="cfg unreadable")
            return
        job_update(jid, status="running")
        cfg["_job"] = {"id": jid, "webhook": row["webhook"],
                       "headers": json.loads(row["headers"] or "{}")}
        if not self.eng.start(cfg):
            job_update(jid, status="queued")


queue_runner = None


def start_queue():
    global queue_runner
    if queue_runner is None:
        queue_runner = QueueRunner(engine)
        queue_runner.start()


def queue_len():
    con = dbcon()
    n = con.execute("select count(*) from jobs where status='queued'").fetchone()[0]
    con.close()
    return n


def deliver_webhook(jid, url, headers, payload):
    if not url or not url.startswith(("http://", "https://")):
        job_update(jid, delivered=2, error="bad webhook url")
        return
    if not WEBHOOK_ALLOW_PRIVATE and _is_private_webhook_target(url):
        job_update(jid, delivered=2, error="webhook to a private/internal "
                                          "target is blocked")
        engine.say("webhook blocked (private target): %s" % url[:80])
        return
    headers = _clean_webhook_headers(headers)

    def run():
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        sig = ""
        if SERVICE_TOKEN:
            sig = "sha256=" + hmac.new(SERVICE_TOKEN.encode(), body,
                                       hashlib.sha256).hexdigest()
        last = None
        for attempt in range(3):
            try:
                req = urllib.request.Request(url, data=body, method="POST")
                req.add_header("Content-Type", "application/json")
                req.add_header("User-Agent", "TheTensorTune/" + VERSION)
                if sig:
                    req.add_header("X-TT-Signature", sig)
                for k, v in (headers or {}).items():
                    req.add_header(str(k), str(v))
                with urllib.request.urlopen(req, timeout=15) as r:
                    r.read()
                job_update(jid, delivered=1, attempts=attempt + 1)
                engine.say("webhook delivered (%s)" % url)
                return
            except Exception as e:
                last = e
                time.sleep(4)
        job_update(jid, delivered=2, attempts=3, error=str(last)[:200])
        engine.say("webhook failed after 3 tries: " + str(last)[:120])

    threading.Thread(target=run, daemon=True).start()


_sys = {"ready": False, "info": None}


def sysinfo():
    if not _sys["ready"]:
        info = dict(torch=None, cuda=False, gpu="", transformers=None,
                    peft=None, bitsandbytes=None, accelerate=None,
                    version=VERSION)
        try:
            import torch
            info["torch"] = torch.__version__
            info["cuda"] = torch.cuda.is_available()
            if info["cuda"]:
                info["gpu"] = torch.cuda.get_device_name(0)
        except Exception:
            pass
        for k in ("transformers", "peft", "bitsandbytes", "accelerate"):
            try:
                info[k] = importlib.metadata.version(k)
            except importlib.metadata.PackageNotFoundError:
                pass
        _sys["info"] = info
        _sys["ready"] = True
    return _sys["info"]


def has_lib(name):
    return importlib.util.find_spec(name) is not None


def gguf_export(run_dir, model_id, token=None, mirror=False, quant="q8_0",
                say=lambda m: None):
    run_dir = Path(run_dir)
    adapter, merged = run_dir / "adapter", run_dir / "merged"
    if not merged.exists():
        if not adapter.exists():
            raise RuntimeError("run has no adapter to export")
        import torch
        from peft import PeftModel
        from transformers import AutoModelForCausalLM, AutoTokenizer
        set_mirror(mirror)
        say("unloading cached inference model")
        infer_srv.unload()
        _trim_ram()
        say("loading base model for merge")
        cuda = torch.cuda.is_available()
        dt = torch.bfloat16 if (cuda and torch.cuda.is_bf16_supported()) else \
            (torch.float16 if cuda else torch.float32)
        try:
            base = AutoModelForCausalLM.from_pretrained(
                model_id, dtype=dt, token=token or None)
            tok = AutoTokenizer.from_pretrained(model_id, token=token or None)
        except TypeError:
            base = AutoModelForCausalLM.from_pretrained(
                model_id, torch_dtype=dt, token=token or None)
            tok = AutoTokenizer.from_pretrained(model_id, token=token or None)
        if tok.pad_token is None:
            tok.pad_token = tok.eos_token
        say("merging adapter into base weights")
        model = PeftModel.from_pretrained(base, str(adapter))
        model = model.merge_and_unload()
        model.save_pretrained(merged)
        tok.save_pretrained(merged)
        say("merged model saved: " + str(merged))
        del model, base
        import gc
        gc.collect()
        if cuda:
            torch.cuda.empty_cache()
        _trim_ram()

    from transformers import AutoTokenizer
    tok = AutoTokenizer.from_pretrained(str(merged))
    quant = (quant or "f16").lower()
    if quant in ("f16", "f32", "q8_0"):
        out = run_dir / ("model-%s.gguf" % quant)
        return gguf_convert(merged, out, quant, tok, say)[0]
    lq = find_llama_quantize()
    if not lq:
        raise RuntimeError("k-quant %s needs llama-quantize (build llama.cpp "
                           "and set TT_LLAMA_CPP or put it on PATH)" % quant)
    import subprocess
    tmpf = run_dir / "model-f16.gguf"
    if not tmpf.exists():
        gguf_convert(merged, tmpf, "f16", tok, say)
    out = run_dir / ("model-%s.gguf" % quant)
    say("running llama-quantize %s ..." % quant)
    subprocess.run([lq, str(tmpf), str(out), quant], check=True,
                   capture_output=True, timeout=3600)
    say("gguf written: %s" % out)
    return str(out)


class BgTask:

    def __init__(self):
        self.lock = threading.Lock()
        self.st = dict(phase="idle", kind="", log=[], out="", error="", started=0)

    def status(self):
        with self.lock:
            return dict(self.st)

    def say(self, line):
        with self.lock:
            self.st["log"].append(datetime.now().strftime("%H:%M:%S ") + line)
            del self.st["log"][:-120]

    def start(self, kind, fn):
        with self.lock:
            if self.st["phase"] == "running":
                return False
            self.st = dict(phase="running", kind=kind, log=[], out="",
                           error="", started=time.time())
        def work():
            try:
                out = fn(self.say)
                with self.lock:
                    self.st.update(phase="done", out=str(out))
            except Exception as e:
                if os.environ.get("TT_DEBUG"):
                    traceback.print_exc()
                with self.lock:
                    self.st.update(phase="error", error=str(e)[:300])
        threading.Thread(target=work, daemon=True).start()
        return True


task = BgTask()


def _nullctx():
    import contextlib
    return contextlib.nullcontext()


class Inference:

    def __init__(self):
        self.lock = threading.Lock()
        self.key = None
        self.model = None
        self.tok = None

    def unload(self):
        with self.lock:
            self.model = self.tok = None
            self.key = None
        import gc
        gc.collect()
        try:
            import torch
            if torch.cuda.is_available():
                torch.cuda.empty_cache()
        except Exception:
            pass

    def ensure(self, model_id, adapter_dir=None, merged_dir=None,
               token=None, mirror=False, say=lambda m: None):
        key = (model_id, adapter_dir, merged_dir)
        with self.lock:
            if self.key == key and self.model is not None:
                return self.model, self.tok
        self.unload()
        import torch
        from transformers import AutoModelForCausalLM, AutoTokenizer
        set_mirror(mirror)
        cuda = torch.cuda.is_available()
        dt = torch.bfloat16 if (cuda and torch.cuda.is_bf16_supported()) else \
            (torch.float16 if cuda else torch.float32)
        src = merged_dir or model_id
        kw = dict(dtype=dt)
        if token:
            kw["token"] = token
        try:
            model = AutoModelForCausalLM.from_pretrained(src, **kw)
        except TypeError:
            kw.pop("dtype", None)
            kw["torch_dtype"] = dt
            model = AutoModelForCausalLM.from_pretrained(src, **kw)
        try:
            tok = AutoTokenizer.from_pretrained(
                adapter_dir or merged_dir or model_id, token=token or None)
        except Exception:
            tok = AutoTokenizer.from_pretrained(model_id, token=token or None)
        if tok.pad_token is None:
            tok.pad_token = tok.eos_token
        if adapter_dir:
            from peft import PeftModel
            model = PeftModel.from_pretrained(model, adapter_dir)
        model.eval()
        with self.lock:
            self.key, self.model, self.tok = key, model, tok
        return model, tok

    def generate(self, messages, max_new=64, temperature=0.7, base=False):
        import torch
        model, tok = self.model, self.tok
        has_tpl = bool(getattr(tok, "chat_template", None))
        if messages and has_tpl:
            out = tok.apply_chat_template(messages, tokenize=True,
                                          add_generation_prompt=True)
            ids = out["input_ids"] if hasattr(out, "keys") else out
            ids = list(ids)[-2048:]
            inp = torch.tensor([ids])
        else:
            text = messages[-1]["content"] if messages else ""
            enc = tok(text, return_tensors="pt")
            inp = enc["input_ids"][:, -2048:]
        max_new = max(1, min(256, int(max_new)))
        gen_kw = dict(max_new_tokens=max_new, pad_token_id=tok.pad_token_id
                      or tok.eos_token_id)
        if temperature and float(temperature) > 0:
            gen_kw.update(do_sample=True, temperature=max(0.05, float(temperature)),
                          top_p=0.9)
        else:
            gen_kw.update(do_sample=False)
        cm = model.disable_adapter() if (base and hasattr(model, "disable_adapter")) \
            else _nullctx()
        with torch.no_grad(), cm:
            out_ids = model.generate(inp, **gen_kw)
        new = out_ids[0][inp.shape[1]:]
        return tok.decode(new, skip_special_tokens=True)


infer_srv = Inference()


def eval_ppl(model, tok, feats, max_n=8):
    import torch
    coll = pad_collate(tok)
    tot, cnt = 0.0, 0
    model.eval()
    with torch.no_grad():
        for i in range(0, min(len(feats), max_n), 1):
            batch = coll(feats[i:i + 1])
            out = model(input_ids=batch["input_ids"],
                        attention_mask=batch["attention_mask"],
                        labels=batch["labels"])
            n = int((batch["labels"] != -100).sum())
            if n:
                tot += float(out.loss) * n
                cnt += n
    if not cnt:
        return None, 0
    return tot / cnt, cnt


def resolve_run(payload):
    rid = payload.get("run_id")
    row = None
    if rid:
        row = run_row(int(rid))
    elif payload.get("out_dir"):
        d = Path(str(payload["out_dir"]))
        try:
            ok = d.resolve().parent == RUNS_DIR.resolve()
        except Exception:
            ok = False
        if not ok:
            return None, "out_dir outside the runs directory is not allowed"
        c = d / "config.json"
        if c.exists():
            try:
                cfg = json.loads(c.read_text(encoding="utf-8"))
            except Exception:
                return None, "run cfg unreadable"
            return {"id": None, "out_dir": str(d), "cfg": cfg}, None
        return None, "out_dir has no config.json"
    if not row:
        return None, "run not found"
    try:
        cfg = json.loads(row["cfg"])
    except Exception:
        return None, "run cfg unreadable"
    if not row["out_dir"]:
        return None, "run has no output dir yet"
    return {"id": row["id"], "out_dir": row["out_dir"], "cfg": cfg}, None


def comparison_payload(run_id, prompt=None, max_new=48, n_samples=8):
    import torch
    row, err = resolve_run({"run_id": run_id})
    if err:
        raise RuntimeError(err)
    cfg = row["cfg"]
    out_dir = Path(row["out_dir"])
    adapter = out_dir / "adapter"
    if not adapter.exists():
        raise RuntimeError("this run has no adapter")
    m = cfg["model"]
    model, tok = infer_srv.ensure(m["id"], adapter_dir=str(adapter),
                                  token=m.get("token") or None,
                                  mirror=bool(m.get("mirror")))
    hp = cfg.get("params") or {}
    maxlen = int(hp.get("maxlen") or 1024)
    feats = []
    samples = []
    dsp = cfg.get("dataset_path")
    if dsp and Path(dsp).exists():
        samples = parse_samples(Path(dsp).read_text(encoding="utf-8"))
        feats, _, _ = build_features(tok, samples, maxlen, True)
    if not prompt:
        prompt = "Hello, introduce yourself."
        if samples and samples[0]["kind"] == "chat":
            users = [x["content"] for x in samples[0]["messages"] if x["role"] == "user"]
            if users:
                prompt = users[-1]
        elif samples and samples[0]["kind"] == "pc":
            prompt = samples[0]["prompt"]
    msgs = [{"role": "user", "content": prompt}]

    def gen(base_mode=False):
        return infer_srv.generate(msgs, max_new=max_new, temperature=0.3,
                                  base=base_mode)

    is_peft = hasattr(model, "disable_adapter")
    with torch.no_grad():
        base_ppl, base_tok_n = (None, 0)
        if feats:
            if is_peft:
                with model.disable_adapter():
                    base_ppl, base_tok_n = eval_ppl(model, tok, feats, n_samples)
            else:
                base_ppl, base_tok_n = eval_ppl(model, tok, feats, n_samples)
        base_gen = gen(True)
        tuned_ppl, tuned_tok_n = (None, 0)
        if feats:
            tuned_ppl, tuned_tok_n = eval_ppl(model, tok, feats, n_samples)
        tuned_gen = gen()

    def ppl_block(loss, n):
        if loss is None:
            return {"loss": None, "ppl": None, "tokens": n}
        return {"loss": round(loss, 4), "ppl": round(math.exp(min(20, loss)), 2),
                "tokens": n}

    return {
        "run_id": run_id, "model": m["id"], "prompt": prompt,
        "samples_used": min(len(feats), n_samples) if feats else 0,
        "base": {"ppl": ppl_block(base_ppl, base_tok_n), "gen": base_gen},
        "tuned": {"ppl": ppl_block(tuned_ppl, tuned_tok_n), "gen": tuned_gen},
        "delta_loss": (round(base_ppl - tuned_ppl, 4)
                       if base_ppl is not None and tuned_ppl is not None else None),
    }


