@app.before_request
def check_auth():
    if request.method in ("POST", "PUT", "DELETE", "PATCH"):
        origin = (request.headers.get("Origin") or "").strip()
        if origin:
            try:
                from urllib.parse import urlsplit
                oh = urlsplit(origin).hostname or ""
            except Exception:
                oh = ""
            if oh and oh not in (request.host.split(":")[0], "localhost",
                                 "127.0.0.1", "[::1]"):
                return jsonify({"error": "cross-origin request blocked"}), 403
    if not SERVICE_TOKEN:
        return None
    p = request.path
    if not p.startswith("/api/") or p == "/api/health":
        return None
    tok = request.headers.get("X-TT-Token") or ""
    if not tok:
        ah = request.headers.get("Authorization") or ""
        if ah.lower().startswith("bearer "):
            tok = ah[7:].strip()
    if not tok or not hmac.compare_digest(tok.encode(), SERVICE_TOKEN.encode()):
        return jsonify({"error": "unauthorized",
                        "hint": "send X-TT-Token: <token>"}), 401
    return None


