def validate_start(c):
    if not (has_lib("torch") and has_lib("transformers") and has_lib("peft")):
        return None, ("training stack missing: "
                      "pip install torch transformers peft accelerate")
    m = c.get("model") or {}
    mid = (m.get("custom") or "").strip() or (m.get("preset") or "").strip()
    if not mid:
        return None, "no model selected"
    did = c.get("dataset_id") or ""
    path = safe_dataset_path(did)
    if not did or path is None or not path.exists():
        return None, "dataset missing"
    lp, hp = c.get("lora") or {}, c.get("params") or {}
    try:
        for v, cast in [(hp.get("lr"), float), (hp.get("epochs"), float),
                        (hp.get("warmup"), float), (hp.get("bs"), int),
                        (hp.get("gacc"), int), (hp.get("maxlen"), int),
                        (hp.get("seed"), int), (hp.get("eval_pct"), float),
                        (hp.get("patience"), int),
                        (lp.get("r"), int), (lp.get("alpha"), int),
                        (lp.get("dropout"), float)]:
            if v not in (None, ""):
                cast(v)
    except (TypeError, ValueError):
        return None, "bad numeric value in the training blocks"
    samples = parse_samples(path.read_text(encoding="utf-8"))
    if len(samples) < 2:
        return None, "dataset too small"
    cfg = {"model": {"id": mid, "token": (m.get("token") or "").strip(),
                    "mirror": bool(m.get("mirror"))},
           "dataset_id": did, "dataset_path": str(path), "samples": len(samples),
           "lora": lp, "params": hp, "output": c.get("output") or {}}
    return cfg, None


