@app.post("/api/infer")
def api_infer():
    if engine.busy:
        return jsonify({"error": "training in progress, inference is "
                       "blocked while the engine is busy"}), 409
    j = request.get_json(silent=True) or {}
    row, err = resolve_run(j)
    if err:
        return jsonify({"error": err}), 404
    cfg = row["cfg"]
    out_dir = Path(row["out_dir"])
    mode = j.get("mode") or "auto"
    adapter = out_dir / "adapter" if (out_dir / "adapter").exists() else None
    merged = out_dir / "merged" if (out_dir / "merged").exists() else None
    if mode == "adapter" and not adapter:
        return jsonify({"error": "run has no adapter"}), 400
    if mode == "base" and not adapter and not merged:
        return jsonify({"error": "run has no adapter"}), 400
    if mode == "auto" and not adapter and not merged:
        return jsonify({"error": "run has no adapter"}), 400
    m = cfg["model"]
    try:
        if mode == "base" and adapter:
            infer_srv.ensure(m["id"], adapter_dir=str(adapter),
                             token=m.get("token") or None,
                             mirror=bool(m.get("mirror")))
        else:
            use_merged = merged if (mode == "auto" and merged and not adapter) else None
            infer_srv.ensure(m["id"], adapter_dir=str(adapter) if adapter else None,
                             merged_dir=str(use_merged) if use_merged else None,
                             token=m.get("token") or None,
                             mirror=bool(m.get("mirror")))
        msgs = j.get("messages")
        if not msgs and j.get("prompt"):
            msgs = [{"role": "user", "content": str(j["prompt"])}]
        if not msgs:
            return jsonify({"error": "messages or prompt required"}), 400
        t0 = time.time()
        text = infer_srv.generate(msgs, j.get("max_new") or 64,
                                  j.get("temperature") if j.get("temperature") is not None else 0.7,
                                  base=(mode == "base"))
        return jsonify({"text": text, "mode": mode, "elapsed": round(time.time() - t0, 1)})
    except Exception as e:
        hint = explain_error(e)
        return jsonify({"error": (hint + " | " if hint else "") + str(e)[:200]}), 500


@app.post("/api/compare")
def api_compare():
    if engine.busy:
        return jsonify({"error": "training in progress"}), 409
    j = request.get_json(silent=True) or {}
    if not j.get("run_id"):
        con = dbcon()
        rows = con.execute("select id from runs where out_dir != '' "
                           "order by id desc limit 30").fetchall()
        con.close()
        for r in rows:
            row = run_row(r["id"])
            try:
                cfg = json.loads(row["cfg"])
            except Exception:
                continue
            if (Path(row["out_dir"]) / "adapter").exists():
                j["run_id"] = r["id"]
                break
        if not j.get("run_id"):
            return jsonify({"error": "no finished run with an adapter yet"}), 404
    try:
        t0 = time.time()
        payload = comparison_payload(int(j["run_id"]), j.get("prompt"),
                                     j.get("max_new") or 48,
                                     j.get("samples") or 8)
        payload["elapsed"] = round(time.time() - t0, 1)
        return jsonify(payload)
    except Exception as e:
        hint = explain_error(e)
        return jsonify({"error": (hint + " | " if hint else "") + str(e)[:200]}), 500


@app.get("/api/runs")
def api_runs():
    con = dbcon()
    rows = con.execute("select id, ts, model, samples, status, loss, eval_loss, "
                       "dur, out_dir from runs order by id desc limit 60").fetchall()
    con.close()
    out = []
    for r in rows:
        d = dict(r)
        if d.get("out_dir"):
            p = Path(d["out_dir"])
            d["ckpt"] = bool(latest_checkpoint(p))
            d["adapter"] = (p / "adapter").exists()
            d["merged"] = (p / "merged").exists()
            d["gguf"] = next((x.name for x in p.glob("model-*.gguf")), None)
        else:
            d["ckpt"] = d["adapter"] = d["merged"] = False
            d["gguf"] = None
        out.append(d)
    return jsonify(out)


@app.post("/api/runs/clear")
def api_runs_clear():
    con = dbcon()
    with con:
        con.execute("delete from runs")
        con.execute("delete from jobs")
    con.close()
    return jsonify({"ok": True})


@app.get("/api/settings")
def api_settings_get():
    con = dbcon()
    rows = con.execute("select k, v from settings").fetchall()
    con.close()
    return jsonify({r["k"]: r["v"] for r in rows})


@app.post("/api/settings")
def api_settings_set():
    data = request.get_json(silent=True) or {}
    con = dbcon()
    with con:
        con.executemany("insert or replace into settings(k, v) values(?, ?)",
                        [(k, str(v)) for k, v in data.items()])
    con.close()
    if "mirror" in data:
        set_mirror(data["mirror"] in (True, 1, "1", "True", "true"))
    return jsonify({"ok": True})


